const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const canvas=document.querySelector('#society'),ctx=canvas.getContext('2d'),slider=document.querySelector('#influence'),pause=document.querySelector('#pause');
let width=450,height=135,agents=[],running=!reduced,lastTime=0,phase=0;
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;canvas.width=Math.round(width*devicePixelRatio);canvas.height=Math.round(height*devicePixelRatio);ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}
function reset(){agents=Array.from({length:60},(_,i)=>{const base=((i*37)%61)/61;return{base,x:12+base*(width-24),y:14+((i*19)%107)/107*(height-28),seed:i*.81}});draw()}
function draw(){ctx.clearRect(0,0,width,height);const majority=width*.8;ctx.strokeStyle='#665044';ctx.setLineDash([2,5]);ctx.beginPath();ctx.moveTo(majority,8);ctx.lineTo(majority,height-5);ctx.stroke();ctx.setLineDash([]);for(let i=0;i<agents.length;i++){const a=agents[i];for(let j=i+1;j<agents.length;j++){const b=agents[j],d=Math.hypot(a.x-b.x,a.y-b.y);if(d<32){ctx.strokeStyle='rgba(217,136,102,'+((1-d/32)*.17)+')';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}ctx.fillStyle=a.x>width*.58?'#eb6252':'#c8b9a8';ctx.beginPath();ctx.arc(a.x,a.y,2.7,0,Math.PI*2);ctx.fill()}}
function frame(t){if(running&&t-lastTime>30){lastTime=t;phase+=.025;const influence=Number(slider.value)/100;for(const a of agents){const preference=a.base*(1-influence)+.8*influence;const target=12+preference*(width-24)+Math.sin(phase+a.seed)*4;a.x+=(target-a.x)*.035;a.y=14+((a.seed/.81*19)%107)/107*(height-28)+Math.sin(phase*.5+a.seed)*3}draw()}requestAnimationFrame(frame)}
function sync(){pause.textContent=running?'Pause Ⅱ':'Play ▷';pause.setAttribute('aria-label',running?'Pause social simulation':'Play social simulation');pause.setAttribute('aria-pressed',String(!running))}
slider.addEventListener('input',()=>{document.querySelector('#influence-value').textContent=slider.value+'%';if(!running){const v=Number(slider.value)/100;agents.forEach(a=>a.x=12+(a.base*(1-v)+.8*v)*(width-24));draw()}});pause.addEventListener('click',()=>{running=!running;sync()});document.querySelector('#reset').addEventListener('click',()=>{slider.value='0';document.querySelector('#influence-value').textContent='0%';reset()});new ResizeObserver(()=>{resize();reset()}).observe(canvas);resize();reset();sync();requestAnimationFrame(frame);
const cobraImage=document.querySelector('#cobra-image'),cobraToggle=document.querySelector('#cobra-toggle');let cobraPlaying=!reduced;
function syncCobra(){cobraImage.src=cobraPlaying?cobraImage.dataset.animated:'assets/cobra-poster.jpg';cobraToggle.textContent=cobraPlaying?'Pause demo Ⅱ':'Play demo ▷';cobraToggle.setAttribute('aria-pressed',String(cobraPlaying))}cobraToggle.addEventListener('click',()=>{cobraPlaying=!cobraPlaying;syncCobra()});syncCobra();
const phases=[['READ THE ORIGINAL STUDY','Start with a published human-subject experiment.'],['PRESERVE THE PROTOCOL','Reconstruct its stimuli, conditions, and procedures.'],['RUN SIMULATED PARTICIPANTS','Explore how different agent designs behave.'],['COMPARE WITH HUMAN FINDINGS','Evaluate agreement in conclusions and effect sizes.']];let hubRunning=!reduced,hubStep=0;const hubToggle=document.querySelector('#hub-toggle');function updateHub(){document.querySelectorAll('.stage').forEach((e,i)=>e.classList.toggle('active',i===hubStep));document.querySelector('#hub-phase').textContent=phases[hubStep][0];document.querySelector('#hub-description').textContent=phases[hubStep][1];document.querySelector('#hub-step-count').textContent='0'+(hubStep+1)+' / 04';document.querySelector('#hub-progress').style.width=((hubStep+1)*25)+'%'}function syncHub(){hubToggle.textContent=hubRunning?'Pause Ⅱ':'Play ▷';hubToggle.setAttribute('aria-label',hubRunning?'Pause HumanStudy-Hub animation':'Play HumanStudy-Hub animation');hubToggle.setAttribute('aria-pressed',String(!hubRunning))}hubToggle.addEventListener('click',()=>{hubRunning=!hubRunning;syncHub()});setInterval(()=>{if(hubRunning&&!document.hidden){hubStep=(hubStep+1)%4;updateHub()}},2400);syncHub();
document.querySelectorAll('[data-open]').forEach(a=>a.addEventListener('click',()=>document.getElementById(a.dataset.open).open=true));if(location.hash==='#publications')document.querySelector('#pub-details').open=true;
